<?php
require_once __DIR__ . '/_bootstrap.php';customerPostCsrf();$message='';if($_SERVER['REQUEST_METHOD']==='POST'){$subject=trim((string)($_POST['subject']??''));$body=trim((string)($_POST['message']??''));if($subject===''||$body==='')$message='Subject and message are required.';else{customerQuery('INSERT INTO support_tickets (user_id,subject,message,status) VALUES (?,?,?,?)',[$customerId,$subject,$body,'open']);$message='Your support request was sent. Our team will respond shortly.';}}$tickets=customerRows('SELECT id,subject,message,status,created_at FROM support_tickets WHERE user_id=? ORDER BY created_at DESC LIMIT 30',[$customerId]);customerPageStart('Support centre','Support');?><div class="cw-title"><div><h1>Support centre</h1><p>Our team is here to help with orders, payments and sourcing.</p></div></div><?php if($message):?><div class="cw-alert"><?=e($message)?></div><?php endif;?><div class="cw-grid cw-grid-2"><section class="cw-card"><h2>Start a conversation</h2><form class="cw-form" method="post"><?=csrfField()?><label>Subject<input name="subject" required placeholder="How can we help?"></label><label>Message<textarea name="message" required placeholder="Include your order number if relevant"></textarea></label><button class="cw-btn" type="submit">Send request</button></form></section><section class="cw-card"><h2>Your requests</h2><?php if(!$tickets):?><div class="cw-empty">No support requests. We usually reply within one business day.</div><?php else:foreach($tickets as $t):?><article style="padding:13px 0;border-bottom:1px solid #e7edf5"><strong><?=e($t['subject'])?></strong> <span class="badge"><?=e($t['status'])?></span><p class="muted"><?=e($t['message'])?></p><small class="muted"><?=e($t['created_at'])?></small></article><?php endforeach;endif;?></section></div><?php customerPageEnd();?>